def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp_coops = sum(1 for h in history if h[1] == 'C')

    if opp_coops == 0:
        return 'D'
    if opp_coops == n:
        return 'D'

    last_opp = history[-1][1]
    last_me = history[-1][0]

    if last_opp == 'D':
        if rng.random() < 0.6:
            return 'D'
        else:
            return 'C'
    else:
        if last_me == 'D':
            if opp_coops / n > 0.8:
                return 'D'
            return 'C'
        if opp_coops / n > 0.85 and n > 10:
            if rng.random() < 0.1:
                return 'D'
        return 'C'
